INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Beziehungstyp?', 2, '[{"text": "Verbindung zwischen Entitäten", "correct": true, "because": "Datenbankbeziehungen"}, {"text": "Hardwareverbindung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Beziehungstyp?', 3, '[{"text": "Daten verknüpfen", "correct": true, "because": "Zusammenhänge darstellen"}, {"text": "Systemleistung steigern", "correct": false, "because": "Indirekt"}, {"text": "Kosten senken", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungstypen gibt es in Datenbanken?', 5, '[{"text": "1:1 (eins zu eins)", "correct": true, "because": "Einzigartige Zuordnung"}, {"text": "1:n (eins zu viele)", "correct": true, "because": "Ein Element, viele Zuordnungen"}, {"text": "n:n (viele zu viele)", "correct": true, "because": "Viele Zuordnungen"}, {"text": "1:0 (eins zu null)", "correct": false, "because": "Kein Standardtyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein 1:n-Beziehungstyp erfordert einen Fremdschlüssel. b) Er wird nur in SQL-Datenbanken genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Datenbanken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition eines Beziehungstyps?', 4, '[{"text": "Schlüsselbeziehungen", "correct": false, "because": "Grundlage"}, {"text": "Kardinalität", "correct": false, "because": "Definiert Zuordnung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein n:n-Beziehungstyp eine Zwischentabelle benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "Verknüpfungstabelle nötig"}, {"text": "Nein", "correct": false, "because": "Standardpraxis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Beziehungstyp beschreibt "Ein Kunde hat viele Bestellungen"?', 3, '[{"text": "1:n", "correct": true, "because": "Ein Kunde, viele Bestellungen"}, {"text": "1:1", "correct": false, "because": "Nur eine Zuordnung"}, {"text": "n:n", "correct": false, "because": "Viele zu viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Modellierung eines Beziehungstyps?', 5, '[{"text": "Primärschlüssel", "correct": true, "because": "Identifiziert Entitäten"}, {"text": "Fremdschlüssel", "correct": true, "because": "Verknüpft Entitäten"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein 1:1-Beziehungstyp ist selten. b) Er wird nur für Tabellen mit Primärschlüsseln genutzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch ohne Primärschlüssel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Beziehungstyp unwichtig?', 4, '[{"text": "Kardinalität", "correct": false, "because": "Definiert Zuordnung"}, {"text": "Schlüssel", "correct": false, "because": "Verknüpfung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Beziehungstyp dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein klar definierter Beziehungstyp?', 4, '[{"text": "Datenintegrität", "correct": true, "because": "Konsistenz"}, {"text": "Effiziente Abfragen", "correct": true, "because": "Optimierte Zugriffe"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein n:n-Beziehungstyp immer kompliziert ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Zwischentabelle einfach"}, {"text": "Ja", "correct": false, "because": "Standardlösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Beziehungstyp?', 3, '[{"text": "Kardinalität", "correct": true, "because": "Definiert Beziehung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein 1:n-Beziehungstyp nutzt Fremdschlüssel. b) Er ist nur für große Datenbanken nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Datenbanken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlecht definierter Beziehungstyp?', 5, '[{"text": "Dateninkonsistenz", "correct": true, "because": "Fehlende Klarheit"}, {"text": "Schwierige Abfragen", "correct": true, "because": "Unklare Verknüpfung"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Beziehungstypen?', 3, '[{"text": "Modellierung definieren", "correct": true, "because": "Datenbankdesign"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Beziehungstyp in einem ER-Diagramm dargestellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Entity-Relationship"}, {"text": "Nein", "correct": false, "because": "Standardmethode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Beziehungstypen nutzen?', 4, '[{"text": "MySQL Workbench", "correct": true, "because": "Datenbankmodellierung"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
